DROP POLICY "Students mark their assignments submitted" ON public.student_assignments;
CREATE POLICY "Students mark their assignments submitted" ON public.student_assignments FOR UPDATE TO authenticated USING (student_id = auth.uid() AND status = 'assigned') WITH CHECK (student_id = auth.uid() AND status = 'submitted');
CREATE OR REPLACE FUNCTION public.guard_student_assignment_submission() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF auth.uid() = OLD.student_id AND auth.uid() IS DISTINCT FROM OLD.teacher_id AND NOT public.has_role(auth.uid(), 'admin') THEN IF OLD.status <> 'assigned' OR NEW.status <> 'submitted' OR (to_jsonb(NEW) - 'status' - 'updated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'updated_at') THEN RAISE EXCEPTION 'Students may only submit their own assigned work'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_student_assignment_submission BEFORE UPDATE ON public.student_assignments FOR EACH ROW EXECUTE FUNCTION public.guard_student_assignment_submission();